  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Hesperidin, a large polar glycoside with high transferability to the query, was detected in mouse brain after oral administration, demonstrating that glycoside-containing polyphenols can achieve CNS distribution despite high MW and TPSA.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A phenylethanoid glycoside was detected in rat hippocampus and striatum after oral administration, providing independent evidence that neutral glycosides can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A glucuronide nucleoside analogue showed a CSF/plasma ratio of only 0.04 in monkeys, indicating that some polar glycoside-like conjugates have poor BBB penetration; however, its anionic glucuronide character makes it less transferable to the neutral query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the most transferable experimental evidence (C04, C07) shows that large neutral glycosides can achieve CNS distribution, overriding the physicochemical prior of low passive permeability. The single contradictory glucuronide result (C08) is less applicable due to its anionic charge. Overall, meaningful CNS access is supported.",
  "evidence_gaps": [
    "No direct etoposide brain or CSF measurement is provided.",
    "C04 and C07 are oral natural-product glycosides rather than IV etoposide pharmacokinetics.",
    "Efflux-transporter status of the query is not directly measured.",
    "C08 is an anionic glucuronide, limiting its transferability to the neutral query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "glycoside CNS penetration"
    }
  ],
  "revision_action": "initial"
}

